// Recovers the wizard choice (parts.generic) of parts made with the "Generic
// part" wizard before the choice was stored, by regenerating every choice the
// wizard offers and matching on what it wrote. Pure; scripts/backfill-generic.ts
// does the I/O.
//
// A part matches a choice when:
// - "exact": its name, MPN and manufacturer are what the choice generates, or
// - "mpn": its MPN (non-empty) and manufacturer are — the name was edited by
//   hand or generated by an older version of the wizard.
// Exact matches win. More than one choice at the same strength is ambiguous
// and left alone; so is a part nothing matches (made by hand).

import { GENERIC_FAMILIES } from "@/lib/generic-families";
import {
  rangeParam,
  selectCombinations,
  specFor,
  type GeneratedPart,
  type GenericSpec,
  type GenericType,
  type GenericValues,
  type RangeParam,
} from "@/lib/generic-parts";

export type BackfillPart = { id: string; name: string; mpn: string; manufacturer: string };

export type BackfillMatch =
  | { kind: "exact" | "mpn"; spec: GenericSpec; generated: GeneratedPart }
  | { kind: "ambiguous"; specs: GenericSpec[] }
  | { kind: "none" };

type Combination = { family: string; type: GenericType; values: GenericValues; range?: RangeParam };

const norm = (s: string) => s.trim().toLowerCase();

/** Every reachable select combination of every type, computed once. */
export function allCombinations(): Combination[] {
  return GENERIC_FAMILIES.flatMap((family) =>
    family.types.flatMap((type) =>
      [...selectCombinations(type)].map((values) => ({
        family: family.id,
        type,
        values,
        range: rangeParam(type.params(values)),
      })),
    ),
  );
}

/**
 * Range values worth trying for a part: every number in its name and MPN
 * ("M3×8" → 3, 8; "XHP-4" → 4), so lengths typed in by hand are found too,
 * not only the common ones.
 */
function rangeCandidates(part: BackfillPart): string[] {
  return [...new Set(`${part.name} ${part.mpn}`.match(/\d+(?:[.,]\d+)?/g) ?? [])];
}

export function matchGenericPart(part: BackfillPart, combinations: Combination[]): BackfillMatch {
  const candidates = rangeCandidates(part);
  const name = norm(part.name);
  const mpn = norm(part.mpn);
  const manufacturer = norm(part.manufacturer);
  const found: Record<"exact" | "mpn", { spec: GenericSpec; generated: GeneratedPart }[]> = { exact: [], mpn: [] };

  for (const combo of combinations) {
    const tries = combo.range
      ? candidates.flatMap((raw) => {
          const value = combo.range!.parse(raw);
          return value === null ? [] : [{ ...combo.values, [combo.range!.id]: value }];
        })
      : [combo.values];
    for (const values of tries) {
      const generated = combo.type.generate(values);
      if ("error" in generated || norm(generated.manufacturer) !== manufacturer) continue;
      const sameMpn = norm(generated.mpn) === mpn;
      const hit = { spec: specFor(combo.family, combo.type, values), generated };
      if (sameMpn && norm(generated.name) === name) found.exact.push(hit);
      else if (sameMpn && mpn) found.mpn.push(hit);
    }
  }

  for (const kind of ["exact", "mpn"] as const) {
    const hits = dedupe(found[kind]);
    if (hits.length === 1) return { kind, ...hits[0] };
    if (hits.length > 1) return { kind: "ambiguous", specs: hits.map((h) => h.spec) };
  }
  return { kind: "none" };
}

// The same choice can be reached twice (a number in the name tried as two
// candidates that parse alike: "5,7" and "5.7").
function dedupe<T extends { spec: GenericSpec }>(hits: T[]): T[] {
  const seen = new Map<string, T>();
  for (const hit of hits) seen.set(JSON.stringify(hit.spec), hit);
  return [...seen.values()];
}

/** One UPDATE per match, guarded so a part that got a spec meanwhile keeps it. */
export function backfillSql(matches: { id: string; spec: GenericSpec }[]): string {
  const quote = (s: string) => `'${s.replace(/'/g, "''")}'`;
  return [
    "BEGIN;",
    ...matches.map(
      ({ id, spec }) =>
        `UPDATE parts SET generic = ${quote(JSON.stringify(spec))}::jsonb WHERE id = ${quote(id)} AND generic IS NULL;`,
    ),
    "COMMIT;",
    "",
  ].join("\n");
}
